import{_ as a,C as r,o,c as n,j as p,a as s,E as l,a5 as i}from"./chunks/framework.DNkHA0lr.js";const k=JSON.parse('{"title":"面向未来的宣言(如何在未来10年保持相关性)","description":"","frontmatter":{"title":"面向未来的宣言(如何在未来10年保持相关性)","originalTitle":"The Future-Proof Manifesto (How To Stay Relevant In The Next 10 Years)","date":"2025-05-06","originalUrl":"https://thedankoe.com/letters/the-future-proof-manifesto-how-to-stay-relevant-in-the-next-10-years/","minutes":7,"sourceHash":"fa7031327a26aa6e2a9f9619db5ce350c8dd0ddd7d853896826f64522d0e336f","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-future-proof-manifesto-how-to-stay-relevant-in-the-next-10-years/"}]]},"headers":[],"relativePath":"letters/the-future-proof-manifesto-how-to-stay-relevant-in-the-next-10-years.md","filePath":"letters/the-future-proof-manifesto-how-to-stay-relevant-in-the-next-10-years.md"}'),h={name:"letters/the-future-proof-manifesto-how-to-stay-relevant-in-the-next-10-years.md"};function f(c,e,d,m,u,b){const t=r("ArticleMeta");return o(),n("div",null,[e[0]||(e[0]=p("h1",{id:"面向未来的宣言-如何在未来10年保持相关性",tabindex:"-1"},[s("面向未来的宣言(如何在未来10年保持相关性) "),p("a",{class:"header-anchor",href:"#面向未来的宣言-如何在未来10年保持相关性","aria-label":'Permalink to "面向未来的宣言(如何在未来10年保持相关性)"'},"​")],-1)),l(t),e[1]||(e[1]=i('<p><a href="https://www.youtube.com/embed/encqErQFKoE?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>以下是如何让自己面向未来,从而在接下来的10年里保持相关性的方法:</p><h2 id="变得无需许可" tabindex="-1">变得无需许可 <a class="header-anchor" href="#变得无需许可" aria-label="Permalink to &quot;变得无需许可&quot;">​</a></h2><p>你生活在历史上最无需许可的时代。</p><p>当你不经许可就动手去做事情时,你就在为自己面向未来做准备。你追求自己真正在乎的事情,学习新技能,构建项目,把它打包起来,尝试卖出去,并吸引一群与你能量相符的紧密社群。</p><p>如果你死守着一项曾经是资产、如今却成了负债的技能,那你并没有在为自己面向未来做准备。这种负债会让别<em>人</em>来决定你的价值,限制你的收入上限,并控制你一天中大部分的注意力。</p><p>你可以比过去任何人都更快地学会任何一项技能。</p><p>你几乎可以找到做任何事所需的知识。</p><p>作为一个人,凭借更少的时间、工作量和资金,你能做到的事,比过去一整个公司能做的还多。</p><p>你不需要学位。</p><p>你不需要资格证书。</p><p>你需要的是能拿出结果。</p><p>这被称为<em>无需许可的杠杆</em>。</p><p>令我震惊的是,人们竟然还在选择那条常规路径。</p><p>他们会去读四年大学,背上一大堆债务,把自己锁死在一个学习领域——不是因为他们有足够的经验去做出这个选择,而是因为它承诺给他们一份稳定的收入,而不是去尝试自己的路径,花1-2年时间纠错,培养出一种能让自己赚到想要的钱的心态和技能组合。</p><p>但现在……</p><p>现在,权力在个人手中。</p><p>现在,未来的成功归结为技能、能动性、批判性思维,以及与恐惧、失败和尴尬之间的健康关系。</p><p>如果你不这么认为,那就把上一句再读一遍,因为对自己缺乏信心,恰恰说明你以上这些都不具备。</p><p>但这是可以改变的:</p><h2 id="成为一名创作者" tabindex="-1">成为一名创作者 <a class="header-anchor" href="#成为一名创作者" aria-label="Permalink to &quot;成为一名创作者&quot;">​</a></h2><p>在当今世界,唯一真正的安全网,就是一份无法被忽视的作品集。</p><p>找到一件你真正在乎的事情。</p><p>对它痴迷。不停地拆解它。不管有没有证书和学位,都要成为这方面的专家。</p><p>把它当作你一生的事业。</p><p>把这一切都公开地做出来。</p><p><strong>从精神层面来看:</strong></p><p>创作者不是一个“个人品牌”。</p><p>创作者是你存在的本质。</p><p>人类是工具制造者,是深度通才。不像动物那样只能在特定的细分领域中生存——比如狮子在大草原上——人类会为寒冷制造夹克,为炎热制造风扇。大自然并不是我们所设想的那种慈爱、平和的存在。它残酷、危险,根本不在乎你的感受。正是通过我们创造的欲望,我们才把地球变成了一个更适宜居住的地方,这都要归功于我们所接受的“创作者”这一角色。</p><blockquote><p>如果幸福——或者说愉悦——是取得进步与为比自己更宏大的事物做出贡献这两者的结合,而这两者都是通过解决问题(为自己也为他人)来实现的,而问题又是通过创造力来解决的,那么你未来唯一合乎逻辑、也最根本的目标,就是通过成为一名创作者来体现创造力。</p><p>——<a href="https://thedankoe.com/purpose" target="_blank" rel="noreferrer">《目标与利润》</a></p></blockquote><p>换句话说,你要找到目标与利润的交汇点,方法是为<em>你</em>认为有趣的问题创造解决方案,把这些解决方案传递出去,为人类的进步做出贡献,然后在下一批更复杂的问题出现时,重复这个过程。</p><p><strong>从文化层面来看:</strong></p><p>创作者正在构建新的意义、教育与经济体系。</p><p>人们对“信息类产品”嗤之以鼻,可事实上,从来没有哪个时代能让人以这么低的成本、按照自己的兴趣,向那些(大多数)身体力行、言行一致的人学习。你不必是马可·奥勒留(Marcus Aurelius),才能接触到这个国度里最好的数学家来向他学习了。你只需要在YouTube上搜索一下就行。</p><p>人们对宗教机构和正规教育的信任度下降,并不是因为大众“觉醒了”,而是因为现在有了更多的选择。</p><p>如今,个人可以找到与自己世界观相近、最适合自己学习的创作者。</p><p>你不再受限于父母那一套信仰体系。</p><p>你不再受限于一套僵化课程所能提供的教育。</p><p>你不再被困在一份你讨厌的工作或职业里,因为你现在能获得资源,去追寻你真正的使命。</p><p><strong>从实用层面来看:</strong></p><p>现在,每一家企业都是一家媒体公司。</p><p>从报纸到广播再到电视,而你现在,他妈的直接就能上网。</p><p>你不需要任何人许可,就可以写代码、发推文、写邮件通讯、写书、录视频、录播客、联系潜在客户、提供数字化的自由职业服务、打造数字产品,或者去追求你一生的事业。你不需要许可,就能通过做自己在乎的事情来创作并谋生。</p><p>要开始,先勾勒出你最能帮助的那个人的故事线。</p><p>他们现在在哪里,他们想去哪里,以及从A点到B点这段旅程会是什么样子。这才是吸引受众的关键:转变的可能性。心态上的转变、他们需要掌握的技能,以及需要采取的步骤。你是一个“清晰度的创造者”。</p><p>这就是你的品牌使命——帮助尽可能多的人到达B点。</p><p>你的产品是一套精简的系统,帮助他们从A点走到B点。这可以是自由职业、教练辅导,或是数字产品,比如一本书、Substack上的付费邮件通讯、课程、训练营、一个用氛围编程(vibe-coded)做出来的小应用,或者你见过任何创作者卖过的东西。</p><p>你的内容(用来把合适的人吸引到你和你的产品这边)是那些能让处于A点的人产生共鸣的经验、洞见、观点和观察。</p><p>在你的内容里,重点讲<em>是什么</em>和<em>为什么</em>。</p><p>在你的产品里,重点讲<em>怎么做</em>。</p><p>如果你不知道自己想为谁创作,或者想创作什么:</p><p>那就为你自己创作。</p><p>因为如果每个人都去帮助过去那个版本的自己——考虑到每个人都略有不同,而且人是会随时间演变的——那么创作者经济中就根本不存在“饱和”这种事。</p><h2 id="成为一名初学者" tabindex="-1">成为一名初学者 <a class="header-anchor" href="#成为一名初学者" aria-label="Permalink to &quot;成为一名初学者&quot;">​</a></h2><p>当世界快速变化时,你能做的最重要的事就是学习。</p><p>但大多数人在毕业后就停止了学习,即便在那之前,也可以说他们其实并没有真正<em>学到</em>什么,因为学习是一种发现,而不是记忆。</p><p>如果你想让自己面向未来,就必须愿意改变你所做的事以及做事的方式。</p><p>你并不是对某项具体技能充满热情。</p><p>你并不是对写作、设计之类的东西充满热情。</p><p>如果你陷入了“这些就是我的热情所在”这种陷阱,那么当我们做这些事情的<em>方式</em>发生改变时——尤其是随着AI加速发展——你将经历一番痛苦。</p><p>你真正热爱的是创造本身。</p><p>用你思维中的创造力,把泥土变成黄金的那个过程。</p><p>你热爱的是这种创造如何帮助另一个人拓展他们的自我认知。</p><blockquote><p>传统教育和过度专业化是一种让人臣服于主导范式/体系的方式。要去研究大自然的普遍性原理,做一个深度通才。</p><p>——丹尼尔·施马赫滕伯格(Daniel Schmachtenberger)</p></blockquote><p>不管这是不是有意为之,这都是一个可以观察到的事实:</p><p>学校被创造出来,是为了通过承诺“专业化”所带来的名望,把最聪明的头脑奴役起来,让他们保持狭隘的思维,不去推翻真正的统治者。</p><p>一位皇家史官——或者说过去那种受过良好教育的雇员——可能会被这个国家视为聪明而有价值的人,但海盗——过去那种高能动性的企业家——却懂得地理、天文导航、船上的船员、船本身、经济学、历史和科学等诸多知识,因为这些才是他们在贸易统治中获得成功所必需的工具。</p><p>这片土地上的统治者确实很有权力,没错(至少比那位专业化的史官更有权力),但他们的权力大小,取决于海盗们愿意以他们所定的价格,让出多少资源给他们。</p><p>要让自己面向未来,就去做数字世界里的海盗。</p><p>学会如何学习。</p><p>学会如何思考。</p><p>学会如何赚钱。</p><p>学会如何领导。</p><p>通过创造这一行为,把以上这些全部做到。</p><p>去写作、去营销、去销售、去设计、去构建,竭尽全力去培养并实现一个你真正在乎的愿景。</p><p>——丹</p><hr><p><a href="/en/letters/the-future-proof-manifesto-how-to-stay-relevant-in-the-next-10-years">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',79))])}const x=a(h,[["render",f]]);export{k as __pageData,x as default};
